 "content": "def transform(grid):
    """Connect diagonally aligned 1 markers; a 6 on that segment projects the other diagonal."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc) and dr != 0:
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                length = abs(dr)
                cells = [(r1 + k * sr, c1 + k * sc) for k in range(length + 1)]
                segments.append((sr, sc, cells))
                for r, c in cells:
                    if grid[r][c] != 6:
                        out[r][c] = 1
    for sr, sc, cells in segments:
        cellset = set(cells)
        for r, c in sixes:
            if (r, c) not in cellset:
                continue
            # Extend along the perpendicular diagonal, over the whole grid.
            pr, pc = sr, -sc
            for sign in (-1, 1):
                rr, cc = r, c
                while 0 <= rr - sign * pr < h and 0 <= cc - sign * pc < w:
                    rr -= sign * pr
                    cc -= sign * pc
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
                    rr += sign * pr
                    cc += sign * pc
    return out
